package com.andye.warmod.phalanx.network;import net.fabricmc.fabric.api.networking.v1.*;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.server.level.ServerLevel;public final class PhalanxNetworking{private static boolean registered;private PhalanxNetworking(){}public static void register(){if(registered)return;PayloadTypeRegistry.clientboundPlay().register(ClientboundPhalanxShotPayload.TYPE,ClientboundPhalanxShotPayload.STREAM_CODEC);PayloadTypeRegistry.clientboundPlay().register(ClientboundPhalanxImpactPayload.TYPE,ClientboundPhalanxImpactPayload.STREAM_CODEC);PayloadTypeRegistry.clientboundPlay().register(ClientboundPhalanxStatePayload.TYPE,ClientboundPhalanxStatePayload.STREAM_CODEC);registered=true;}public static void send(ServerLevel l,CustomPacketPayload p){for(var player:PlayerLookup.level(l))ServerPlayNetworking.send(player,p);}}
